    }
  };

  const formatTime = (dateString) => {
    if (!dateString) return "Recently";
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
  };

  // Full Screen Loading State during deep analytics hydration
  if (isGenerating) {
    return (

















          {generationStatus || "Loading Archives..."}


    );
  }

  return (

 setActiveMenuId(null)}>

      {/* ── HEADER ── */}












            Cognitive Performance Archive



            Review detailed analytics and AI tutor insights for your fully completed neural training sessions.




      {/* ── GRID ARCHIVE ── */}





          {isLoading ? (


    {[...Array(4)].map((_, i) => (


    ))}

) : history.length === 0 ? (







No Completed Archives

You haven't completed any Brain Training exams yet.

          ) : (


              {history.map((session) => {
                const tierInfo = getCognitiveTier(session.progress || 0);

                return (

 { if (editingId !== session.id) onReviewExam(session); }}
                    className="group bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2rem] p-6 shadow-sm hover:shadow-xl hover:border-rose-300 dark:hover:border-rose-700 transition-all duration-300 hover:-translate-y-1.5 cursor-pointer relative flex flex-col h-[220px]"
                  >

                    {/* 3-Dot Absolute Menu Trigger */}
                     { e.stopPropagation(); setActiveMenuId(activeMenuId === session.id ? null : session.id); }}
                      className="absolute top-4 right-4 w-9 h-9 rounded-full hover:bg-slate-100 dark:hover:bg-slate-800 flex items-center justify-center text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 transition-colors z-20"
                    >



                    {/* Dropdown Menu */}
                    {activeMenuId === session.id && (


                         handlePin(e, session.id, session.is_pinned)} className="px-4 py-3 text-left hover:bg-slate-50 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200 flex items-center gap-2">
                           {session.is_pinned ? 'Unpin' : 'Pin'}

                         startRename(e, session.id, session.title)} className="px-4 py-3 text-left hover:bg-slate-50 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200 flex items-center gap-2 border-t border-slate-100 dark:border-slate-700/50">
                           Rename

                         handleDelete(e, session.id)} className="px-4 py-3 text-left hover:bg-red-50 dark:hover:bg-red-900/20 text-red-600 dark:text-red-400 flex items-center gap-2 border-t border-slate-100 dark:border-slate-700/50">
                           Delete


                    )}



                      {/* Dynamic Tier Badge */}

                        {tierInfo.tier}



                    {/* Inline Edit State */}
                    {editingId === session.id ? (


                         setEditTitle(e.target.value)}
                          onClick={(e) => e.stopPropagation()}
