                          className="w-full bg-slate-50 dark:bg-slate-950 border-2 border-rose-400 dark:border-rose-600 rounded-lg text-sm font-bold text-slate-900 dark:text-white px-2 py-1.5 outline-none shadow-inner"
                        />
                         saveRename(e, session.id)} className="w-8 h-8 rounded-lg bg-rose-100 dark:bg-rose-900/40 text-rose-600 dark:text-rose-400 flex items-center justify-center hover:scale-105 transition-transform">

                    ) : (


                        {session.is_pinned && }
