Time Limit


                 setCustomDuration(e.target.value)}
                  className="w-12 bg-transparent text-xl font-black text-slate-900 dark:text-white outline-none border-b border-dashed border-emerald-300 dark:border-emerald-700 focus:border-emerald-500"
                  min="5" max="300"
                />
                Mins





             setCustomDuration(15)} className="flex-1 py-1 rounded-lg bg-slate-100 hover:bg-slate-200 dark:bg-slate-800 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300 text-[10px] font-black transition-colors">15m
             setCustomDuration(30)} className="flex-1 py-1 rounded-lg bg-slate-100 hover:bg-slate-200 dark:bg-slate-800 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300 text-[10px] font-black transition-colors">30m
