               { setShowExitModal(false); if(onLeave) onLeave(); }} className="w-full py-3 rounded-xl bg-rose-600 hover:bg-rose-500 text-white font-bold text-xs shadow-md transition-colors focus:outline-none">
                Confirm Exit




      )}

      {/* CONFIRMATION SUBMIT MODAL */}
      {showSubmitModal && (











Submit Training Session?


                You have answered {totalAnsweredCount} out of {totalQuestionsAllSubjects} prompts.




               setShowSubmitModal(false)} className="w-full py-3 rounded-xl bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 font-bold text-xs hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors focus:outline-none">
                Return

               { setShowSubmitModal(false); handleFinalSubmit(); }} className="w-full py-3 rounded-xl bg-rose-600 hover:bg-rose-500 text-white font-bold text-xs shadow-md transition-colors focus:outline-none">
                Submit Now




      )}

      {/* 🚀 FIXED: AUTO-SUBMIT TIMER EXPIRED MODAL W/ ADD TIME OVERRIDE */}
      {autoSubmitCountdown !== null && (






              {autoSubmitCountdown}




Time's Up!


                Session duration expired. Auto-submitting in {autoSubmitCountdown}s.





                Add Time & Continue

               { setAutoSubmitCountdown(null); handleFinalSubmit(); }} className="flex-1 py-3 rounded-xl bg-rose-600 hover:bg-rose-500 text-white font-bold text-[11px] uppercase tracking-wider shadow-md transition-colors focus:outline-none">
                Submit Now




      )}

  );
}



